          "id": "title",
          "component": "Text",
          "variant": "h2",
          "text": "Everest Base Camp Trek Packing List (October)"
        },
        {
          "id": "assumptionsCard",
          "component": "Card",
          "child": "assumptionsColumn"
        },
        {
          "id": "assumptionsColumn",
          "component": "Column",
          "children": [
            "assumptionsTitle",
            "assumptionsList"
          ]
        },
        {
          "id": "assumptionsTitle",
          "component": "Text",
          "variant": "h4",
          "text": "Assumptions"
        },
        {
          "id": "assumptionsList",
          "component": "List",
          "direction": "vertical",
          "children": [
            "assumption1",
            "assumption2",
            "assumption3",
            "assumption4"
          ]
        },
        {
          "id": "assumption1",
          "component": "Text",
          "text": "• The trek is 10 days on the trail, not including travel days to/from Kathmandu/Lukla."
        },
        {
          "id": "assumption2",
          "component": "Text",
          "text": "• A porter will carry your main luggage (duffel bag), so a smaller daypack is also needed for daily essentials."
        },
        {
          "id": "assumption3",
          "component": "Text",
          "text": "• You will be staying in teahouses, so a tent and cooking equipment are not required."
        },
        {
          "id": "assumption4",
          "component": "Text",
          "text": "• Temperatures range from 15°C during the day at lower altitudes to -10°C or colder at night and higher altitudes."
        },
        {
